<?php
declare(strict_types=1);
session_start();
$config = require __DIR__ . '/config.php';
if (is_file(__DIR__ . '/config.local.php')) $config = require __DIR__ . '/config.local.php';
date_default_timezone_set($config['timezone'] ?? 'Asia/Jakarta');
function db(): PDO { static $db; global $config; if (!$db) $db = new PDO('mysql:host='.$config['host'].';port='.$config['port'].';dbname='.$config['database'].';charset=utf8mb4', $config['username'], $config['password'], [PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC,PDO::ATTR_EMULATE_PREPARES=>false]); return $db; }
function e($v): string { return htmlspecialchars((string)$v, ENT_QUOTES, 'UTF-8'); }
function go(string $url): never { header('Location: '.$url); exit; }
function menus(): array { return ['dashboard'=>'Ringkasan','customers'=>'Customer','members'=>'Member','treatments'=>'Treatment','products'=>'Barang','stock'=>'Arus Stok','reservations'=>'Reservasi','visits'=>'Kasir','expenses'=>'Keuangan','reports'=>'Laporan','users'=>'Pengguna','subscription'=>'Langganan','settings'=>'Pengaturan']; }
function allowed(string $key): bool { return isset($_SESSION['user']) && (in_array('*',$_SESSION['permissions']??[],true) || in_array($key,$_SESSION['permissions']??[],true)); }
function requireMenu(string $key): void { if(!allowed($key)){http_response_code(403);exit('Akses menu tidak diizinkan.');} }
function csrf(): string { return $_SESSION['csrf'] ??= bin2hex(random_bytes(32)); }
function checkCsrf(): void { if(!hash_equals(csrf(),$_POST['csrf']??'')){http_response_code(419);exit('Sesi formulir kedaluwarsa. Silakan muat ulang.');} }
function v(string $key,string $default=''): string { return trim((string)($_POST[$key]??$default)); }
function normalizePhone(string $phone): string { $digits=preg_replace('/\\D+/','',$phone);return substr($digits,0,1)==='0'?'62'.substr($digits,1):$digits; }
function maskPhone(string $phone): string { $d=preg_replace('/\D+/','',$phone);return strlen($d)<=6?str_repeat('•',strlen($d)):substr($d,0,4).str_repeat('•',max(2,strlen($d)-7)).substr($d,-3); }
function findActiveMember(PDO $pdo,string $code): ?array { $code=trim($code);if($code===''||strlen($code)>30)return null;$q=$pdo->prepare("SELECT m.customer_id,m.member_code,c.name,c.child_name,c.phone FROM members m JOIN customers c ON c.id=m.customer_id WHERE m.member_code=? AND m.status='aktif' AND (m.end_date IS NULL OR m.end_date<'1000-01-01' OR m.end_date>=?) LIMIT 1");$q->execute([$code,date('Y-m-d')]);return $q->fetch()?:null; }
function memberLookupAllowed(): bool { $now=time();$hits=array_filter($_SESSION['member_lookup_hits']??[],fn($t)=>$now-$t<600);if(count($hits)>=12){$_SESSION['member_lookup_hits']=$hits;return false;}$hits[]=$now;$_SESSION['member_lookup_hits']=$hits;return true; }
function layout(string $title,string $content): void { global $config;$subBanner='';
    if(isset($_SESSION['user'])&&!isset($_GET['booking'])){try{$sub=subscriptionInfo(db());if(!$sub['active']||$sub['left']<=7){$inv=subscriptionInvoice(db(),$sub);$subBanner='<div class="notice invoice-note '.($inv['overdue']?'notice-error':'notice-warn').'" role="'.($inv['overdue']?'alert':'status').'"><div class="inv-head"><strong>Tagihan langganan '.e($inv['no']).'</strong><span class="inv-state">'.($inv['overdue']?'Belum dibayar · jatuh tempo '.e(date('d/m/Y',strtotime($inv['due']))):'Jatuh tempo '.e(date('d/m/Y',strtotime($inv['due']))).($sub['left']===0?' (hari ini)':' ('.$sub['left'].' hari lagi)')).'</span></div><div class="inv-body"><span>Paket langganan 30 hari</span><strong>'.($inv['amount']>0?rupiah($inv['amount']):'Hubungi pemilik sistem').'</strong></div>'.($inv['info']!==''?'<div class="inv-pay">'.nl2br(e($inv['info'])).'</div>':'').($inv['overdue']?'<div class="inv-foot">Sistem dalam mode lihat saja sampai tagihan dibayar. Data tidak bisa ditambah atau diubah.</div>':'').'</div>';}}catch(Throwable $ignored){}} $flash=$_SESSION['flash']??'';$flashError=!empty($_SESSION['flash_error']);unset($_SESSION['flash'],$_SESSION['flash_error']);$publicBooking=isset($_GET['booking']);$page=$publicBooking?'booking':($_GET['page']??'dashboard');$account=isset($_SESSION['user'])?($publicBooking?'<span><a href="index.php">Panel admin</a> · <a href="index.php?logout=1">Keluar</a></span>':'<span>'.e($_SESSION['user']['name']).' <a href="?logout=1">Keluar</a></span>'):'';$navigation=isset($_SESSION['user'])&&!$publicBooking?'<nav>'.implode('',array_map(fn($k,$label)=>allowed($k)?'<a class="'.($page===$k?'active':'').'" href="?page='.$k.'">'.$label.'</a>':'',array_keys(menus()),menus())).'</nav>':'';echo '<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'.e($title).' · '.e($config['app_name']).'</title><link rel="stylesheet" href="style.css"><link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/select2@4.1.0-rc.0/dist/css/select2.min.css"></head><body><header><a class="brand" href="'.($publicBooking?'reservasi.php':'?'). '"><span class="brand-mark" aria-hidden="true"><i></i><i></i><i></i></span>'.e($config['app_name']).'</a>'.$account.'</header>'.$navigation.'<main><div class="pagehead"><div><h1>'.e($title).'</h1></div></div>'.$subBanner.($flash?'<div class="notice'.($flashError?' notice-error':'').'" role="'.($flashError?'alert':'status').'">'.e($flash).'</div>':'').$content.'</main><footer>'.e($config['app_name']).' · Rawat si kecil dengan sentuhan lembut</footer><script src="https://cdn.jsdelivr.net/npm/jquery@3.7.1/dist/jquery.min.js"></script><script src="https://cdn.jsdelivr.net/npm/select2@4.1.0-rc.0/dist/js/select2.min.js"></script><script>if(window.jQuery&&jQuery.fn.select2){window.initS2=function(el){var $=jQuery,keep=$(el).hasClass("keep-empty");$(el).select2({width:"100%",matcher:function m(p,d){if(!p.term||p.term.trim()==="")return d;if(d.children){var out=[];for(var i=0;i<d.children.length;i++){var r=m(p,d.children[i]);if(r)out.push(r)}if(!out.length)return null;var c=$.extend({},d,true);c.children=out;return c}var t=p.term.toLowerCase().trim(),h=(d.element&&d.element.getAttribute&&d.element.getAttribute("data-search"))||d.text.toLowerCase();return (h.indexOf(t)>-1||(t.replace(/[^a-z0-9]+/g,"")!==""&&h.indexOf(t.replace(/[^a-z0-9]+/g,""))>-1))?d:null},placeholder:keep?undefined:$(el).find("option:first").text(),allowClear:!keep,language:{noResults:function(){return "Tidak ditemukan"},searching:function(){return "Mencari..."}}})};window.resetS2=function(el){var $e=jQuery(el);if($e.data("select2"))$e.select2("destroy");window.initS2(el)};jQuery(function($){$(".searchable-select, #catalog-select").each(function(){window.initS2(this)})})}</script></body></html>'; }
function formToken(): string { return '<input type="hidden" name="csrf" value="'.e(csrf()).'">'; }
function table(array $headers,array $rows): string { $html='<div class="tablewrap"><table><thead><tr>';foreach($headers as $h)$html.='<th>'.e($h).'</th>';$html.='</tr></thead><tbody>';if(!$rows)$html.='<tr><td colspan="'.count($headers).'" class="empty">Belum ada data.</td></tr>';foreach($rows as $row){$html.='<tr>';foreach($row as $cell)$html.='<td>'.$cell.'</td>';$html.='</tr>';}$html.='</tbody></table></div>';return $html; }
function customerOptionsHtml(PDO $pdo,int $selected=0): string { $rows=$pdo->query("SELECT c.id,c.name,c.child_name,c.phone,m.member_code FROM customers c LEFT JOIN members m ON m.customer_id=c.id AND m.status='aktif' AND m.start_date<=CURDATE() AND (m.end_date IS NULL OR m.end_date<'1000-01-01' OR m.end_date>=CURDATE()) ORDER BY c.name")->fetchAll();$groups=['member'=>'','other'=>''];
    foreach($rows as $c){$isMember=($c['member_code']??null)!==null;$text=($isMember?$c['member_code'].' · ':'').$c['name'].' · '.$c['child_name'].(!empty($c['phone'])?' · '.$c['phone']:'');$hay=$text.' '.preg_replace('/\D+/','',(string)($c['phone']??'')).' '.preg_replace('/[^A-Za-z0-9]+/','',(string)($c['member_code']??''));$groups[$isMember?'member':'other'].='<option value="'.(int)$c['id'].'" data-member="'.($isMember?1:0).'" data-search="'.e(mb_strtolower($hay)).'" '.($selected===(int)$c['id']?'selected':'').'>'.e($text).'</option>';}
    return ($groups['member']!==''?'<optgroup label="Member aktif">'.$groups['member'].'</optgroup>':'').($groups['other']!==''?'<optgroup label="Customer biasa (bukan member)">'.$groups['other'].'</optgroup>':''); }
function listState(): array { $search=mb_substr(trim((string)($_GET['q']??'')),0,80);$per=(int)($_GET['per']??10);if(!in_array($per,[10,25,50],true))$per=10;return [$search,$per,max(1,(int)($_GET['p']??1))]; }
function searchWhere(array $cols,string $search,array &$params): string { $parts=[];foreach(preg_split('/\s+/u',$search,-1,PREG_SPLIT_NO_EMPTY) as $word){$like='%'.addcslashes($word,'%_\\').'%';$or=[];foreach($cols as $col){$or[]="$col LIKE ?";$params[]=$like;}$parts[]='('.implode(' OR ',$or).')';}return implode(' AND ',$parts); }
function paginate(int $total,int $pg,int $per): array { $pages=max(1,(int)ceil($total/$per));$pg=min($pg,$pages);return [$pg,$pages,($pg-1)*$per]; }
function pagedList(PDO $pdo,string $select,string $from,array $cols,string $order,string $extraWhere='',array $extraParams=[]): array { [$search,$per,$pg]=listState();$params=[];$where=searchWhere($cols,$search,$params);if($extraWhere!==''){$where=$where!==''?'('.$where.') AND ('.$extraWhere.')':$extraWhere;$params=array_merge($params,$extraParams);}$cnt=$pdo->prepare("SELECT COUNT(*) FROM $from".($where?" WHERE $where":''));$cnt->execute($params);$total=(int)$cnt->fetchColumn();[$pg,$pages,$offset]=paginate($total,$pg,$per);$st=$pdo->prepare("SELECT $select FROM $from".($where?" WHERE $where":'')." ORDER BY $order LIMIT $per OFFSET $offset");$st->execute($params);return ['rows'=>$st->fetchAll(),'total'=>$total,'search'=>$search,'per'=>$per,'pg'=>$pg,'pages'=>$pages,'offset'=>$offset]; }
function listUrl(string $page,array $L,array $override=[],array $extra=[]): string { $q=array_merge(['page'=>$page,'q'=>$L['search'],'per'=>$L['per']==10?'':$L['per'],'p'=>$L['pg']>1?$L['pg']:''],$extra,$override);return '?'.http_build_query(array_filter($q,fn($x)=>$x!==''&&$x!==null)); }
function listToolbar(string $page,array $L,string $placeholder,string $extraFields='',array $extra=[]): string { $html='<form method="get" class="searchbar" role="search"><input type="hidden" name="page" value="'.e($page).'"><label class="searchbox"><span class="sr-only">Cari</span><input type="search" name="q" value="'.e($L['search']).'" placeholder="'.e($placeholder).'" maxlength="80"></label>'.$extraFields.'<label class="perpage"><span>Tampil</span><select name="per" onchange="this.form.submit()">';foreach([10,25,50] as $n)$html.='<option value="'.$n.'" '.($L['per']===$n?'selected':'').'>'.$n.'</option>';$html.='</select></label><button class="primary">Cari</button>';if($L['search']!==''||$extra)$html.='<a class="smallbtn" href="?page='.e($page).'">Reset</a>';return $html.'</form>'; }
function listPager(string $page,array $L,array $extra=[]): string { $total=$L['total'];$pg=$L['pg'];$pages=$L['pages'];$per=$L['per'];$from=$total?$L['offset']+1:0;$to=min($total,$L['offset']+$per);$html='<div class="pager"><span class="muted">'.($total?'Menampilkan '.$from.'–'.$to.' dari '.$total.' data':($L['search']!==''?'Tidak ada data yang cocok dengan “'.e($L['search']).'”.':'Belum ada data.')).'</span>';if($pages>1){$html.='<nav aria-label="Halaman" class="pagelinks">';$link=fn($n,$label,$cls='')=>'<a class="pagelink '.$cls.'" href="'.e(listUrl($page,$L,['p'=>$n>1?$n:''],$extra)).'"'.($cls==='current'?' aria-current="page"':'').'>'.$label.'</a>';$html.=$pg>1?$link($pg-1,'&lsaquo; Sebelumnya','wide'):'';$last=0;foreach(range(1,$pages) as $n){if($n===1||$n===$pages||abs($n-$pg)<=1){if($last&&$n-$last>1)$html.='<span class="pagegap">…</span>';$html.=$link($n,(string)$n,$n===$pg?'current':'');$last=$n;}}$html.=$pg<$pages?$link($pg+1,'Berikutnya &rsaquo;','wide'):'';$html.='</nav>';}return $html.'</div>'; }
function rowActions(string $page,int $id,string $deleteAction): string { $label=$page==='users'?'Nonaktifkan':'Hapus';return '<div class="rowactions"><a class="smallbtn" href="?page='.e($page).'&edit='.$id.'">Edit</a><form method="post" onsubmit="return confirm(\'Yakin '.strtolower($label).' data ini?\')">'.formToken().'<input type="hidden" name="action" value="'.e($deleteAction).'"><input type="hidden" name="id" value="'.$id.'"><button class="smallbtn danger">'.$label.'</button></form></div>'; }
function reservationBookingCode(array $r): string { return (string)($r['booking_code']??'OBS'.str_pad((string)$r['id'],6,'0',STR_PAD_LEFT)); }
function reservationWaMessage(array $r,string $kind,array $old=[]): string { global $pdo;$biz=notaSettings($pdo)['name'];$when=date('d/m/Y H:i',strtotime($r['reserved_at']));$code=reservationBookingCode($r);$hi='Halo '.$r['name'].', ';$treatment=trim(($r['code']?$r['code'].' · ':'').$r['treatment']);
    switch($kind){
        case 'konfirmasi': return $hi.'reservasi '.$biz.' untuk '.$r['child_name'].' pada '.$when.' telah dikonfirmasi. Treatment: '.$treatment.'. Kode booking: '.$code.'. Kami tunggu kedatangannya, ya!';
        case 'tolak': return $hi.'mohon maaf, reservasi '.$biz.' untuk '.$r['child_name'].' pada '.$when.' ('.$treatment.') tidak dapat kami proses dan dibatalkan. Silakan pilih jadwal lain di '.appBaseUrl().'/reservasi.php atau balas pesan ini, kami bantu aturkan. Terima kasih.';
        case 'ubah':
            $lines=[];if(!empty($old['reserved_at'])&&$old['reserved_at']!==$r['reserved_at'])$lines[]='Jadwal: '.date('d/m/Y H:i',strtotime($old['reserved_at'])).' menjadi '.$when;if(!empty($old['treatment'])&&$old['treatment']!==$treatment)$lines[]='Treatment: '.$old['treatment'].' menjadi '.$treatment;
            return $hi.'ada perubahan pada reservasi '.$biz.' untuk '.$r['child_name'].".\n".implode("\n",$lines).($lines?"\n":'').'Status: '.$r['status'].'. Kode booking: '.$code.'. Jika kurang sesuai, silakan balas pesan ini.';
        case 'menunggu': return $hi.'reservasi '.$biz.' untuk '.$r['child_name'].' pada '.$when.' ('.$treatment.') sudah kami terima dan sedang menunggu konfirmasi. Kode booking: '.$code.'. Kami kabari lagi segera, ya.';
        default: return $hi.'kami dari '.$biz.' terkait reservasi '.$r['child_name'].' pada '.$when.' ('.$treatment.'). Kode booking: '.$code.'.';
    } }
function waUrl(string $phone,string $message): string { return 'https://wa.me/'.normalizePhone($phone).'?text='.rawurlencode($message); }
function waButton(array $r,string $kind,string $label,array $old=[],string $class='smallbtn wa-link'): string { return '<a class="'.$class.'" target="_blank" rel="noopener" href="'.e(waUrl((string)$r['phone'],reservationWaMessage($r,$kind,$old))).'">'.e($label).'</a>'; }
function reservationRowActions(array $r): string { $csrf=formToken();$id=(int)$r['id'];$status=$r['status'];
    $post=fn($action,$label,$cls,$confirm='')=>'<form method="post"'.($confirm?' onsubmit="return confirm(\''.$confirm.'\')"':'').'>'.$csrf.'<input type="hidden" name="action" value="'.$action.'"><input type="hidden" name="id" value="'.$id.'"><button class="smallbtn '.$cls.'">'.$label.'</button></form>';
    $html='';
    if($status==='Menunggu')$html.=$post('reservation_approve','Setujui','primary-mini').$post('reservation_reject','Tolak','danger','Tolak reservasi ini? Status menjadi Batal dan jam dibuka kembali.').waButton($r,'menunggu','Kabari WA');
    elseif($status==='Dikonfirmasi')$html.=waButton($r,'konfirmasi','Kirim WA').$post('reservation_reject','Batalkan','danger','Batalkan reservasi ini? Status menjadi Batal dan jam dibuka kembali.');
    elseif($status==='Batal')$html.=waButton($r,'tolak','Kabari WA');
    else $html.='<span class="muted">Lunas</span>'.waButton($r,'hubungi','Hubungi');
    if($status!=='Selesai')$html.='<a class="smallbtn" href="?page=reservations&edit='.$id.'">Edit</a>';
    if($status!=='Selesai')$html.=$post('reservation_delete','Hapus','danger','Hapus reservasi ini?');
    return '<div class="rowactions rowwrap">'.$html.'</div>'; }
function rupiah($n): string { return 'Rp '.number_format((float)$n,0,',','.'); }
function subscriptionInfo(PDO $pdo): array { static $c=null; if($c!==null)return $c; $end=$pdo->query('SELECT MAX(end_date) FROM subscriptions')->fetchColumn(); if(!$end){$c=['active'=>true,'end'=>null,'left'=>null];return $c;} $left=(int)floor((strtotime((string)$end)-strtotime(date('Y-m-d')))/86400); $c=['active'=>$left>=0,'end'=>(string)$end,'left'=>$left]; return $c; }
function subscriptionInvoice(PDO $pdo,array $sub): array { global $config; $n=(int)$pdo->query('SELECT COUNT(*) FROM subscriptions')->fetchColumn()+1; $price=(float)($config['license_price']??0); return ['no'=>'INV-'.date('Ym',strtotime($sub['end']??'today')).'-'.str_pad((string)$n,3,'0',STR_PAD_LEFT),'amount'=>$price,'due'=>$sub['end'],'overdue'=>!$sub['active'],'info'=>trim((string)($config['license_payment_info']??''))]; }
function spvPinState(PDO $pdo,array $config): string { $h=$pdo->query("SELECT setting_value FROM app_settings WHERE setting_key='spv_pin_hash'")->fetchColumn();if($h)return 'db';return trim((string)($config['spv_pin']??''))!==''?'config':'none'; }
function spvPinCheck(PDO $pdo,array $config,string $pin): bool { $h=$pdo->query("SELECT setting_value FROM app_settings WHERE setting_key='spv_pin_hash'")->fetchColumn();if($h)return $pin!==''&&password_verify($pin,(string)$h);$c=trim((string)($config['spv_pin']??''));return $c!==''&&hash_equals($c,$pin); }
function cashTotal(PDO $pdo): array {
    $sales=(float)$pdo->query("SELECT COALESCE(SUM(amount*quantity),0) FROM visits WHERE payment_method='Tunai'")->fetchColumn();
    $r=$pdo->query("SELECT COALESCE(SUM(CASE WHEN kind='masuk' THEN amount ELSE 0 END),0) inc,COALESCE(SUM(CASE WHEN kind='keluar' THEN amount ELSE 0 END),0) ex FROM expenses WHERE source='Kas'")->fetch();
    return ['sales'=>$sales,'income'=>(float)$r['inc'],'spent'=>(float)$r['ex'],'balance'=>$sales+(float)$r['inc']-(float)$r['ex']];
}
function cashBalance(PDO $pdo): array {
    $oq=$pdo->prepare("SELECT * FROM shifts WHERE status='buka' AND opened_by=? ORDER BY id DESC LIMIT 1");$oq->execute([(int)($_SESSION['user']['id']??0)]);$open=$oq->fetch();
    if($open){$t=shiftTotals($pdo,(int)$open['id']);return ['balance'=>(float)$open['opening_cash']+$t['cash']+$t['income']-$t['expense'],'shift'=>$open,'base'=>(float)$open['opening_cash'],'sales'=>$t['cash'],'income'=>$t['income'],'spent'=>$t['expense'],'closed_at'=>null,'has_history'=>true];}
    $last=$pdo->query("SELECT * FROM shifts WHERE status='tutup' ORDER BY id DESC LIMIT 1")->fetch();
    $q=$pdo->prepare("SELECT COALESCE(SUM(CASE WHEN kind='keluar' THEN amount ELSE 0 END),0),COALESCE(SUM(CASE WHEN kind='masuk' THEN amount ELSE 0 END),0) FROM expenses WHERE source='Kas' AND shift_id IS NULL AND expense_date>?");$q->execute([$last?$last['closed_at']:'1970-01-01 00:00:00']);[$spent,$income]=array_map('floatval',$q->fetch(PDO::FETCH_NUM));
    $base=$last?(float)$last['counted_cash']:0.0;
    return ['balance'=>$base+$income-$spent,'shift'=>null,'base'=>$base,'sales'=>0.0,'income'=>$income,'spent'=>$spent,'closed_at'=>$last['closed_at']??null,'has_history'=>(bool)$last];
}
function shiftReportHtml(PDO $pdo,int $id): string {
    $q=$pdo->prepare("SELECT s.*,o.name opener,c.name closer FROM shifts s JOIN users o ON o.id=s.opened_by LEFT JOIN users c ON c.id=s.closed_by WHERE s.id=? AND s.status='tutup'");$q->execute([$id]);$s=$q->fetch();
    if(!$s)return '<p class="muted">Laporan shift tidak ditemukan.</p>';
    $t=shiftTotals($pdo,$id);$nota=notaSettings($pdo);
    $row=fn($l,$v,$b=false)=>'<div class="t-row'.($b?' t-bold':'').'"><span>'.e($l).'</span><span>'.e($v).'</span></div>';
    $line='<div class="t-line"></div>';$diff=(float)$s['difference'];
    $ex=$pdo->prepare('SELECT category,description,amount,source,kind FROM expenses WHERE shift_id=? ORDER BY id');$ex->execute([$id]);$exRows=$ex->fetchAll();
    $h='<article class="thermal"><div class="t-center"><strong class="t-name">'.e($nota['name']).'</strong>'.($nota['address']!==''?'<div>'.e($nota['address']).'</div>':'').($nota['phone']!==''?'<div>Telp/WA '.e($nota['phone']).'</div>':'').'</div>'.$line.'<div class="t-center t-bold">LAPORAN SHIFT #'.(int)$s['id'].'</div>'.$line;
    $h.=$row('Dibuka',date('d/m/y H:i',strtotime($s['opened_at']))).'<div class="t-sub">'.e($s['opener']).'</div>'.$row('Ditutup',date('d/m/y H:i',strtotime($s['closed_at']))).'<div class="t-sub">'.e($s['closer']??'-').'</div>'.$row('Jumlah transaksi',(string)$t['trx']).$line;
    $h.=$row('Saldo awal kas',rupiah($s['opening_cash'])).$row('Penjualan tunai',rupiah($s['cash_sales'])).$row('Penjualan transfer',rupiah($t['by']['Transfer'])).$row('Penjualan QRIS',rupiah($t['by']['QRIS'])).$row('Penjualan lainnya',rupiah($t['by']['Lainnya'])).$row('Total penjualan',rupiah($t['cash']+$t['noncash']),true).$line;
    $h.=$row('Pemasukan manual',rupiah($s['cash_income']??0)).$row('Pengeluaran kas',rupiah($s['cash_expenses']??0),true);
    foreach($exRows as $x)$h.='<div class="t-sub">'.($x['kind']==='masuk'?'+ ':'- ').e($x['category'].($x['description']?' ('.$x['description'].')':'')).' '.e(rupiah($x['amount'])).($x['source']==='Kas'?'':' [non-kas]').'</div>';
    $h.=$line.$row('Kas seharusnya',rupiah($s['expected_cash']),true).$row('Kas fisik',rupiah($s['counted_cash']),true).$row('Selisih',($diff>0?'+':'').rupiah($diff),true).$line;
    if(!empty($s['open_notes']))$h.='<div class="t-sub">Catatan buka: '.e($s['open_notes']).'</div>';
    if(!empty($s['close_notes']))$h.='<div class="t-sub">Catatan tutup: '.e($s['close_notes']).'</div>';
    $h.='<div class="t-sign"><div>Kasir</div><div>Pemilik/Atasan</div></div><div class="t-sign-space"></div><div class="t-sign"><div>(__________)</div><div>(__________)</div></div><div class="t-center t-sub">Dicetak '.date('d/m/Y H:i').'</div></article>';
    return $h;
}
function shiftHistoryHtml(PDO $pdo): string {
    $rs=$pdo->query("SELECT s.*,o.name opener,c.name closer FROM shifts s JOIN users o ON o.id=s.opened_by LEFT JOIN users c ON c.id=s.closed_by WHERE s.status='tutup' ORDER BY s.id DESC LIMIT 100")->fetchAll();$signed=fn($n)=>((float)$n>0?'+':'').rupiah($n);
    $rows=array_map(fn($r)=>['#'.(int)$r['id'],e($r['opened_at']),e($r['closed_at']),e($r['opener'].' / '.($r['closer']??'-')),rupiah($r['opening_cash']),rupiah($r['cash_sales']),rupiah($r['cash_expenses']??0),rupiah($r['expected_cash']),rupiah($r['counted_cash']),e($signed($r['difference'])),'<button type="button" class="smallbtn js-shift-report" data-id="'.(int)$r['id'].'">Lihat / cetak</button> <form method="post" class="inline-form" onsubmit="return confirm(\'Hapus riwayat shift #'.(int)$r['id'].'? Transaksi dan pengeluaran tetap ada, hanya laporan shift ini yang dihapus.\')">'.formToken().'<input type="hidden" name="action" value="shift_delete"><input type="hidden" name="id" value="'.(int)$r['id'].'"><button class="smallbtn danger">Hapus</button></form>'],$rs);
    return table(['No.','Dibuka','Ditutup','Kasir buka / tutup','Saldo awal','Tunai','Pengeluaran','Kas seharusnya','Kas fisik','Selisih','Aksi'],$rows);
}
function shiftDialogsHtml(PDO $pdo,?array $open,array $others=[]): string {
    $h='<dialog id="shift-open-dialog" class="modal"><form method="post" class="modal-form">'.formToken().'<div class="modal-head"><h2>Buka shift</h2><button type="button" class="modal-x" data-close aria-label="Tutup">&times;</button></div><p class="muted">Masukkan saldo awal kas di laci sebelum mulai menerima pembayaran.</p><input type="hidden" name="action" value="shift_open">';
    $prefill='0';
    $h.='<label>Saldo awal kas (Rp)<input type="number" name="opening_cash" min="0" step="1" placeholder="0" value="'.e($prefill).'"></label><label>Catatan<input name="open_notes" maxlength="255"></label><div class="modal-actions"><button type="button" class="secondary" data-close>Batal</button><button class="primary">Buka shift</button></div></form></dialog>';
    foreach(array_merge($open?[$open]:[],$others) as $os){$isMine=$open&&(int)$os['id']===(int)$open['id'];
        $t=shiftTotals($pdo,(int)$os['id']);$expected=(float)$os['opening_cash']+$t['cash']+$t['income']-$t['expense'];
        $h.='<dialog id="shift-close-dialog'.($isMine?'':'-'.(int)$os['id']).'" class="modal"><form method="post" class="modal-form shift-close-form">'.formToken().'<div class="modal-head"><h2>Tutup shift'.($isMine?'':' '.e($os['opener'])).'</h2><button type="button" class="modal-x" data-close aria-label="Tutup">&times;</button></div><input type="hidden" name="action" value="shift_close"><input type="hidden" name="id" value="'.(int)$os['id'].'"><dl class="receipt-meta"><dt>Dibuka</dt><dd>'.e($os['opened_at']).'</dd><dt>Saldo awal kas</dt><dd>'.rupiah($os['opening_cash']).'</dd><dt>Penjualan tunai</dt><dd>'.rupiah($t['cash']).' ('.$t['trx'].' transaksi semua metode)</dd><dt>Non-tunai</dt><dd>'.rupiah($t['noncash']).'</dd><dt>Pemasukan manual</dt><dd>'.rupiah($t['income']).'</dd><dt>Pengeluaran kas</dt><dd>'.rupiah($t['expense']).'</dd></dl><div class="receipt-total"><span>Saldo kas toko seharusnya</span><strong>'.rupiah($expected).'</strong></div><label>Kas dihitung fisik (Rp)<input type="number" name="counted_cash" class="counted-cash" min="0" step="1" required></label><label>Selisih<input class="cash-diff" readonly value="-" tabindex="-1" data-expected="'.e((string)$expected).'"></label><label>Catatan penutupan<input name="close_notes" maxlength="255"></label><div class="modal-actions"><button type="button" class="secondary" data-close>Batal</button><button class="primary">Tutup shift</button></div></form></dialog>';
    }
    $h.='<dialog id="shift-history-dialog" class="modal modal-wide"><div class="modal-form"><div class="modal-head"><h2>Riwayat shift</h2><button type="button" class="modal-x" data-close aria-label="Tutup">&times;</button></div><div id="shift-history-body" class="modal-scroll"></div></div></dialog>';
    $h.='<dialog id="shift-report-dialog" class="modal"><div class="modal-form"><div class="modal-head"><h2>Laporan shift</h2><button type="button" class="modal-x" data-close aria-label="Tutup">&times;</button></div><div id="shift-report-body" class="modal-scroll"></div><div class="modal-actions"><button type="button" class="secondary" data-close>Tutup</button><button type="button" class="primary" id="shift-print">Cetak</button></div></div></dialog>';
    $js=<<<'JS'
document.addEventListener("DOMContentLoaded",()=>{
  const $=id=>document.getElementById(id);
  const openD=d=>{if(d&&!d.open)d.showModal()};
  document.querySelectorAll("[data-dialog]").forEach(b=>b.addEventListener("click",()=>openD($(b.dataset.dialog))));
  document.querySelectorAll("dialog.modal").forEach(d=>{d.addEventListener("click",e=>{if(e.target===d)d.close()});d.querySelectorAll("[data-close]").forEach(b=>b.addEventListener("click",()=>d.close()))});
  document.querySelectorAll(".shift-close-form").forEach(f=>{const counted=f.querySelector(".counted-cash"),diff=f.querySelector(".cash-diff");if(!counted||!diff)return;const exp=Number(diff.dataset.expected);counted.addEventListener("input",()=>{if(counted.value===""){diff.value="-";return}const d=Number(counted.value)-exp;diff.value=(d>0?"+":"")+new Intl.NumberFormat("id-ID",{style:"currency",currency:"IDR",maximumFractionDigits:0}).format(d)})});
  async function showReport(id){const body=$("shift-report-body");body.textContent="Memuat laporan...";openD($("shift-report-dialog"));try{const r=await fetch("?page=visits&shift_report="+encodeURIComponent(id),{credentials:"same-origin"});if(!r.ok)throw new Error();body.innerHTML=await r.text()}catch(e){body.textContent="Laporan gagal dimuat."}}
  const hist=$("shift-history-btn");
  if(hist)hist.addEventListener("click",async()=>{const body=$("shift-history-body");body.textContent="Memuat riwayat...";openD($("shift-history-dialog"));try{const r=await fetch("?page=visits&shift_list=1",{credentials:"same-origin"});if(!r.ok)throw new Error();body.innerHTML=await r.text()}catch(e){body.textContent="Riwayat gagal dimuat."}});
  $("shift-history-body").addEventListener("click",e=>{const b=e.target.closest(".js-shift-report");if(b){$("shift-history-dialog").close();showReport(b.dataset.id)}});
  $("shift-print").addEventListener("click",()=>{const src=$("shift-report-body").innerHTML,f=document.createElement("iframe");f.style.cssText="position:fixed;right:0;bottom:0;width:0;height:0;border:0";document.body.appendChild(f);const doc=f.contentWindow.document;doc.open();doc.write("<!doctype html><html><head><meta charset=\"utf-8\"><title>Laporan shift</title><link rel=\"stylesheet\" href=\"style.css\"><style>@page{size:80mm auto;margin:2mm}html,body{background:#fff;margin:0;padding:0}.thermal{width:auto;padding:0;box-shadow:none;border:0}</style></head><body>"+src+"</body></html>");doc.close();f.onload=()=>{f.contentWindow.focus();f.contentWindow.print();setTimeout(()=>f.remove(),1500)}});
  const q=new URLSearchParams(location.search).get("open_report");if(q)showReport(q);
});
JS;
    return $h.'<script>'.$js.'</script>';
}
function logStock(PDO $pdo,int $productId,string $type,int $quantity,int $stockAfter,?float $unitCost,?string $reference,?string $notes): void { $pdo->prepare('INSERT INTO stock_movements(product_id,movement_type,quantity,stock_after,unit_cost,reference,notes,user_id,created_at) VALUES(?,?,?,?,?,?,?,?,?)')->execute([$productId,$type,$quantity,$stockAfter,$unitCost,$reference!==''?$reference:null,$notes!==''?$notes:null,(int)$_SESSION['user']['id'],date('Y-m-d H:i:s')]); }
function notaSettings(PDO $pdo): array {
    global $config;
    $s=$pdo->query("SELECT setting_key,setting_value FROM app_settings WHERE setting_key LIKE 'nota\\_%'")->fetchAll(PDO::FETCH_KEY_PAIR);
    $color=(string)($s['nota_color']??'');if(!preg_match('/^#[0-9a-fA-F]{6}$/',$color))$color='#ec9a85';
    return ['name'=>($s['nota_name']??'')!==''?$s['nota_name']:($config['app_name']??'Baby Spa'),'address'=>$s['nota_address']??'','phone'=>$s['nota_phone']??'','footer'=>array_key_exists('nota_footer',$s)?$s['nota_footer']:'Terima kasih atas kunjungan Anda. Semoga si kecil sehat dan ceria!','logo'=>$s['nota_logo']??'','title'=>($s['nota_title']??'')!==''?$s['nota_title']:'INVOICE','color'=>$color,'bank'=>$s['nota_bank']??'','tagline'=>$s['nota_tagline']??'','style'=>($s['nota_style']??'')==='struk'?'struk':'invoice','paper'=>($s['nota_paper']??'')==='58'?'58':'80'];
}
function notaLogoUrl(array $nota): string { if($nota['logo']==='')return '';$f=__DIR__.'/uploads/'.$nota['logo'];return is_file($f)?'uploads/'.rawurlencode($nota['logo']).'?v='.filemtime($f):''; }
function notaToken(string $code): string { global $config; return substr(hash_hmac('sha256',$code,(string)($config['password']??'').'|nota'),0,24); }
function appBaseUrl(): string { $https=(!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off')||($_SERVER['HTTP_X_FORWARDED_PROTO']??'')==='https';$dir=rtrim(str_replace('\\','/',dirname($_SERVER['SCRIPT_NAME']??'')),'/');return ($https?'https':'http').'://'.($_SERVER['HTTP_HOST']??'localhost').$dir; }
function notaPublicUrl(string $code): string { return appBaseUrl().'/nota.php?c='.rawurlencode($code).'&t='.notaToken($code); }
function receiptData(PDO $pdo,string $code): ?array {
    $q=$pdo->prepare('SELECT v.*,c.name customer,c.child_name,c.phone,c.address caddress,t.treatment_type ttype,t.price tprice,t.member_price tmember,t.code tcode,t.name tname,p.name pname,p.unit punit,u.name staff,th.name therapist FROM visits v JOIN customers c ON c.id=v.customer_id LEFT JOIN treatments t ON t.id=v.treatment_id LEFT JOIN products p ON p.id=v.product_id JOIN users u ON u.id=v.user_id LEFT JOIN users th ON th.id=v.therapist_id WHERE v.transaction_code=? ORDER BY v.id');
    $q->execute([$code]);$rows=$q->fetchAll();
    return $rows?['rows'=>$rows,'first'=>$rows[0]]:null;
}
function renderThermalReceipt(array $d,array $nota): string {
    $f=$d['first'];$total=0.0;$items='';$therapists=[];$riders=[];$logo=notaLogoUrl($nota);$px=$nota['paper']==='58'?219:302;
    $row=fn($l,$v,$b=false)=>'<div class="t-row'.($b?' t-bold':'').'"><span>'.e($l).'</span><span>'.e($v).'</span></div>';$line='<div class="t-line"></div>';
    foreach($d['rows'] as $r){$sub=(float)$r['amount']*(int)$r['quantity'];$total+=$sub;$isTransport=strtolower(trim((string)($r['ttype']??'')))==='transport';
        if($r['item_type']==='product')$name=$r['pname'];else{$isMember=(float)($r['tmember']??0)>0&&(float)$r['amount']===(float)$r['tmember']&&(float)$r['tmember']<(float)$r['tprice'];$name=($isMember?'(Member) ':'').$r['tname'];}
        $note='';if(!empty($r['therapist'])){if($isTransport){$riders[]=$r['therapist'];$note='Motor '.$r['therapist'];}else{$therapists[]=$r['therapist'];$note='Terapis '.$r['therapist'];}}
        $items.='<div class="t-item">'.e($name).'</div>'.($note!==''?'<div class="t-sub">'.e($note).'</div>':'').$row((int)$r['quantity'].' x '.rupiah($r['amount']),rupiah($sub));}
    $h='<style>@page{size:'.($nota['paper']==='58'?'58':'80').'mm auto;margin:2mm}@media print{.thermal{width:100%!important;max-width:none!important;border:0!important;padding:0!important}}</style><article class="thermal" style="width:'.$px.'px"><div class="t-center">'.($logo!==''?'<img class="t-logo" src="'.e($logo).'" alt="">':'').'<strong class="t-name">'.e($nota['name']).'</strong>'.($nota['address']!==''?'<div>'.e($nota['address']).'</div>':'').($nota['phone']!==''?'<div>Telp/WA '.e($nota['phone']).'</div>':'').'</div>'.$line;
    $h.=$row('No. nota','').'<div class="t-sub">'.e($f['transaction_code']).'</div>'.$row('Tanggal',date('d/m/y H:i',strtotime($f['visit_date']))).$row('Customer',$f['customer'].' · '.$f['child_name']).($therapists?$row('Terapis',implode(', ',array_values(array_unique($therapists)))):'').$row('Kasir',(string)$f['staff']).$line.$items.$line;
    $disc=0.0;foreach($d['rows'] as $r)$disc+=max(0.0,(float)($r['discount']??0));if($disc>0)$h.=$row('Diskon/potongan','-'.rupiah($disc));$h.=$row('TOTAL',rupiah($total),true).$row('Pembayaran',(string)$f['payment_method']);
    if(!empty($f['notes']))$h.='<div class="t-sub">Catatan: '.e($f['notes']).'</div>';
    if($nota['bank']!=='')$h.=$line.'<div class="t-sub">'.nl2br(e($nota['bank'])).'</div>';
    $h.=$line.($nota['footer']!==''?'<div class="t-center t-sub">'.e($nota['footer']).'</div>':'').'</article>';
    return $h;
}
function renderReceipt(array $d,array $nota): string {
    if($nota['style']==='struk')return renderThermalReceipt($d,$nota);
    $f=$d['first'];$total=0.0;$rows='';$n=0;$logo=notaLogoUrl($nota);
    $riders=[];$therapists=[];
    foreach($d['rows'] as $r){$sub=(float)$r['amount']*(int)$r['quantity'];$total+=$sub;$n++;$isTransport=strtolower(trim((string)($r['ttype']??'')))==='transport';
        if($r['item_type']==='product')$name=$r['pname'];else{$isMember=(float)($r['tmember']??0)>0&&(float)$r['amount']===(float)$r['tmember']&&(float)$r['tmember']<(float)$r['tprice'];$name=($isMember?'(Member) ':'').$r['tname'];}
        $sub2='';if(!empty($r['therapist'])){if($isTransport){$riders[]=$r['therapist'];$sub2='Motor '.$r['therapist'];}else{$therapists[]=$r['therapist'];$sub2='Terapis '.$r['therapist'];}}
        $rows.='<div class="inv-row '.($n%2?'odd':'even').'"><div class="inv-c-desc"><span>'.e($name).'</span>'.($sub2!==''?'<small>'.e($sub2).'</small>':'').'</div><div class="inv-c-qty">'.(int)$r['quantity'].'</div><div class="inv-c-price">'.e(rupiah($r['amount'])).'</div><div class="inv-c-total">'.e(rupiah($sub)).'</div></div>';}
    for($k=$n;$k<5;$k++)$rows.='<div class="inv-row '.(($k+1)%2?'odd':'even').' blank"><div class="inv-c-desc">&nbsp;</div><div class="inv-c-qty"></div><div class="inv-c-price"></div><div class="inv-c-total"></div></div>';
    $logoHtml=$logo!==''?'<img src="'.e($logo).'" alt="'.e($nota['name']).'">':'<div class="inv-blob"><strong>'.e($nota['name']).'</strong>'.($nota['tagline']!==''?'<small>'.e($nota['tagline']).'</small>':'').'</div>';
    $therapistNames=array_values(array_unique($therapists));
    $contact=trim((string)$f['phone']);$addr=trim((string)($f['caddress']??''));
    $h='<article class="invoice" style="--inv:'.e($nota['color']).'">';
    $h.='<div class="inv-top"><span class="inv-bar"></span><span class="inv-title">'.e($nota['title']).'</span></div>';
    $h.='<div class="inv-mid"><div class="inv-logo">'.$logoHtml.'</div><div class="inv-to"><strong>'.e($nota['title']).' TO :</strong><div class="inv-field"><span>NAMA</span><i>:</i><em>'.e($f['customer'].' · '.$f['child_name']).'</em></div><div class="inv-field"><span>NO. KONTAK</span><i>:</i><em>'.e($contact).'</em></div><div class="inv-field"><span>ALAMAT</span><i>:</i><em>'.e($addr).'</em></div></div></div>';
    $h.='<div class="inv-date"><div><span>TANGGAL :</span> <strong>'.e(date('d/m/Y H:i',strtotime($f['visit_date']))).'</strong></div><div><span>NO. NOTA :</span> <strong>'.e($f['transaction_code']).'</strong></div></div>';
    $h.='<div class="inv-table"><div class="inv-row inv-head"><div class="inv-c-desc">DESKRIPSI ITEM</div><div class="inv-c-qty">JML</div><div class="inv-c-price">HARGA</div><div class="inv-c-total">TOTAL</div></div>'.$rows.'<div class="inv-row odd inv-payrow"><div class="inv-c-desc"><strong>Cara Pembayaran : '.e($f['payment_method']).'</strong></div><div class="inv-c-qty"></div><div class="inv-c-price"></div><div class="inv-c-total"></div></div></div>';
    $h.='<div class="inv-bottom"><div class="inv-bank">'.($nota['bank']!==''?'<strong>Rekening Transfer :</strong><div>'.nl2br(e($nota['bank'])).'</div>':'').'</div><div class="inv-grand"><span>GRAND TOTAL</span><strong>'.e(rupiah($total)).'</strong></div></div>';
    $disc=0.0;foreach($d['rows'] as $r)$disc+=max(0.0,(float)($r['discount']??0));$meta=[];if($disc>0)$meta[]='Hemat '.rupiah($disc);if($therapistNames)$meta[]='Terapis: '.implode(', ',$therapistNames);$meta[]='Kasir: '.$f['staff'];if(!empty($f['notes']))$meta[]='Catatan: '.$f['notes'];
    $h.='<div class="inv-foot"><div class="inv-meta">'.e(implode(' · ',$meta)).'</div>'.($nota['footer']!==''?'<div>'.e($nota['footer']).'</div>':'').'<div class="inv-addr">'.e(trim($nota['name'].($nota['address']!==''?' · '.$nota['address']:'').($nota['phone']!==''?' · Telp/WA '.$nota['phone']:''))).'</div></div></article>';
    return $h;
}
function shiftTotals(PDO $pdo,int $shiftId): array {
    $q=$pdo->prepare("SELECT payment_method,COUNT(DISTINCT COALESCE(transaction_code,CONCAT('legacy-',id))) trx,COALESCE(SUM(amount*quantity),0) total FROM visits WHERE shift_id=? GROUP BY payment_method");$q->execute([$shiftId]);
    $by=['Tunai'=>0.0,'Transfer'=>0.0,'QRIS'=>0.0,'Lainnya'=>0.0];$trx=0;
    foreach($q->fetchAll() as $r){$by[$r['payment_method']]=(float)$r['total'];$trx+=(int)$r['trx'];}
    $q=$pdo->prepare("SELECT COUNT(DISTINCT COALESCE(transaction_code,CONCAT('legacy-',id))) FROM visits WHERE shift_id=?");$q->execute([$shiftId]);
    $e=$pdo->prepare("SELECT COALESCE(SUM(CASE WHEN kind='keluar' THEN amount ELSE 0 END),0) ex,COALESCE(SUM(CASE WHEN kind='masuk' THEN amount ELSE 0 END),0) inc FROM expenses WHERE shift_id=? AND source='Kas'");$e->execute([$shiftId]);$ei=$e->fetch();
    return ['by'=>$by,'cash'=>$by['Tunai'],'noncash'=>$by['Transfer']+$by['QRIS']+$by['Lainnya'],'trx'=>(int)$q->fetchColumn(),'expense'=>(float)$ei['ex'],'income'=>(float)$ei['inc']];
}
function schemaStatements(): array {
    $file=__DIR__.'/schema.sql';
    if(is_file($file)&&is_readable($file)){$sql=file_get_contents($file);if($sql!==false)return array_filter(array_map('trim',explode(';',$sql)));}
    return [
        "CREATE TABLE IF NOT EXISTS users (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, username VARCHAR(60) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, active TINYINT(1) NOT NULL DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci",
        "CREATE TABLE IF NOT EXISTS permissions (user_id INT UNSIGNED NOT NULL, menu VARCHAR(40) NOT NULL, PRIMARY KEY(user_id,menu), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci",
        "CREATE TABLE IF NOT EXISTS customers (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, phone VARCHAR(30) NOT NULL, child_name VARCHAR(120) NOT NULL, birth_date DATE NULL, address VARCHAR(255) NULL, social_media VARCHAR(120) NULL, child_complaint TEXT NULL, weight_kg DECIMAL(5,2) NULL, height_cm DECIMAL(5,2) NULL, notes TEXT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX idx_customer_phone(phone)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci",
        "CREATE TABLE IF NOT EXISTS members (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, customer_id INT UNSIGNED NOT NULL UNIQUE, member_code VARCHAR(30) NOT NULL UNIQUE, start_date DATE NOT NULL, end_date DATE NULL, status ENUM('aktif','nonaktif') NOT NULL DEFAULT 'aktif', FOREIGN KEY(customer_id) REFERENCES customers(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci",
        "CREATE TABLE IF NOT EXISTS treatments (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, code VARCHAR(20) NOT NULL DEFAULT '', name VARCHAR(120) NOT NULL, treatment_type VARCHAR(80) NOT NULL DEFAULT 'Umum', duration_minutes SMALLINT UNSIGNED NOT NULL DEFAULT 60, price DECIMAL(12,2) NOT NULL DEFAULT 0, member_price DECIMAL(12,2) NOT NULL DEFAULT 0, therapist_fee DECIMAL(12,2) NOT NULL DEFAULT 0, active TINYINT(1) NOT NULL DEFAULT 1) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci",
        "CREATE TABLE IF NOT EXISTS products (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, code VARCHAR(24) NOT NULL, name VARCHAR(120) NOT NULL, unit VARCHAR(30) NOT NULL DEFAULT 'pcs', cost_price DECIMAL(12,2) NOT NULL DEFAULT 0, price DECIMAL(12,2) NOT NULL DEFAULT 0, stock INT UNSIGNED NOT NULL DEFAULT 0, active TINYINT(1) NOT NULL DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci",
        "CREATE TABLE IF NOT EXISTS visits (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, transaction_code VARCHAR(32) NULL, customer_id INT UNSIGNED NOT NULL, treatment_id INT UNSIGNED NULL, product_id INT UNSIGNED NULL, item_type ENUM('treatment','product') NOT NULL DEFAULT 'treatment', quantity INT UNSIGNED NOT NULL DEFAULT 1, user_id INT UNSIGNED NOT NULL, visit_date DATETIME NOT NULL, amount DECIMAL(12,2) NOT NULL, payment_method ENUM('Tunai','Transfer','QRIS','Lainnya') NOT NULL DEFAULT 'Tunai', notes VARCHAR(255) NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX idx_visits_date(visit_date), INDEX idx_visits_customer(customer_id,visit_date), INDEX idx_visit_transaction(transaction_code), FOREIGN KEY(customer_id) REFERENCES customers(id) ON DELETE RESTRICT, FOREIGN KEY(treatment_id) REFERENCES treatments(id) ON DELETE RESTRICT, FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE RESTRICT, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci",
        "CREATE TABLE IF NOT EXISTS reservations (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, booking_code VARCHAR(16) NULL UNIQUE, customer_id INT UNSIGNED NOT NULL, treatment_id INT UNSIGNED NOT NULL, user_id INT UNSIGNED NOT NULL, reserved_at DATETIME NOT NULL, status ENUM('Menunggu','Dikonfirmasi','Selesai','Batal') NOT NULL DEFAULT 'Menunggu', notes VARCHAR(255) NULL, visit_id BIGINT UNSIGNED NULL UNIQUE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX idx_reservation_time(reserved_at), FOREIGN KEY(customer_id) REFERENCES customers(id) ON DELETE RESTRICT, FOREIGN KEY(treatment_id) REFERENCES treatments(id) ON DELETE RESTRICT, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE RESTRICT, FOREIGN KEY(visit_id) REFERENCES visits(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci",
