function upgradeSchema(PDO $pdo): void {
    $pdo->exec("CREATE TABLE IF NOT EXISTS products (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, code VARCHAR(24) NOT NULL, name VARCHAR(120) NOT NULL, unit VARCHAR(30) NOT NULL DEFAULT 'pcs', cost_price DECIMAL(12,2) NOT NULL DEFAULT 0, price DECIMAL(12,2) NOT NULL DEFAULT 0, stock INT UNSIGNED NOT NULL DEFAULT 0, active TINYINT(1) NOT NULL DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
    $visitColumns=array_column($pdo->query('SHOW COLUMNS FROM visits')->fetchAll(),'Field');
    $visitAdd=['transaction_code'=>'VARCHAR(32) NULL','product_id'=>'INT UNSIGNED NULL','item_type'=>"ENUM('treatment','product') NOT NULL DEFAULT 'treatment'",'quantity'=>'INT UNSIGNED NOT NULL DEFAULT 1','list_price'=>'DECIMAL(12,2) NULL','discount'=>'DECIMAL(12,2) NOT NULL DEFAULT 0'];
    foreach($visitAdd as $column=>$definition)if(!in_array($column,$visitColumns,true))$pdo->exec("ALTER TABLE visits ADD COLUMN $column $definition");
    $pdo->exec('ALTER TABLE visits MODIFY treatment_id INT UNSIGNED NULL');
    $pdo->exec("CREATE TABLE IF NOT EXISTS discount_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, transaction_code VARCHAR(32) NOT NULL, visit_id BIGINT UNSIGNED NULL, user_id INT UNSIGNED NOT NULL, customer_id INT UNSIGNED NULL, item_type VARCHAR(12) NOT NULL, item_name VARCHAR(160) NOT NULL, quantity INT UNSIGNED NOT NULL DEFAULT 1, list_price DECIMAL(12,2) NOT NULL DEFAULT 0, unit_price DECIMAL(12,2) NOT NULL DEFAULT 0, discount DECIMAL(12,2) NOT NULL DEFAULT 0, final_unit DECIMAL(12,2) NOT NULL DEFAULT 0, reason VARCHAR(200) NULL, created_at DATETIME NOT NULL, INDEX idx_dlog_date(created_at), INDEX idx_dlog_tx(transaction_code)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
    $columns=array_column($pdo->query('SHOW COLUMNS FROM treatments')->fetchAll(),'Field');
    $add=['code'=>"VARCHAR(20) NOT NULL DEFAULT ''",'treatment_type'=>"VARCHAR(80) NOT NULL DEFAULT 'Umum'",'member_price'=>'DECIMAL(12,2) NOT NULL DEFAULT 0','therapist_fee'=>'DECIMAL(12,2) NOT NULL DEFAULT 0'];
    foreach($add as $column=>$definition)if(!in_array($column,$columns,true))$pdo->exec("ALTER TABLE treatments ADD COLUMN $column $definition");
    $customerColumns=array_column($pdo->query('SHOW COLUMNS FROM customers')->fetchAll(),'Field');
    $customerAdd=['social_media'=>'VARCHAR(120) NULL','child_complaint'=>'TEXT NULL','weight_kg'=>'DECIMAL(5,2) NULL','height_cm'=>'DECIMAL(5,2) NULL'];
    foreach($customerAdd as $column=>$definition)if(!in_array($column,$customerColumns,true))$pdo->exec("ALTER TABLE customers ADD COLUMN $column $definition");
    $pdo->exec("CREATE TABLE IF NOT EXISTS reservations (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, booking_code VARCHAR(16) NULL UNIQUE, customer_id INT UNSIGNED NOT NULL, treatment_id INT UNSIGNED NOT NULL, user_id INT UNSIGNED NOT NULL, reserved_at DATETIME NOT NULL, status ENUM('Menunggu','Dikonfirmasi','Selesai','Batal') NOT NULL DEFAULT 'Menunggu', notes VARCHAR(255) NULL, visit_id BIGINT UNSIGNED NULL UNIQUE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX idx_reservation_time(reserved_at), FOREIGN KEY(customer_id) REFERENCES customers(id) ON DELETE RESTRICT, FOREIGN KEY(treatment_id) REFERENCES treatments(id) ON DELETE RESTRICT, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE RESTRICT, FOREIGN KEY(visit_id) REFERENCES visits(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
    $reservationColumns=array_column($pdo->query('SHOW COLUMNS FROM reservations')->fetchAll(),'Field');
    if(!in_array('booking_code',$reservationColumns,true))$pdo->exec('ALTER TABLE reservations ADD COLUMN booking_code VARCHAR(16) NULL');
    $reservationIndexes=array_column($pdo->query('SHOW INDEX FROM reservations')->fetchAll(),'Key_name');
    if(!in_array('booking_code',$reservationIndexes,true))$pdo->exec('ALTER TABLE reservations ADD UNIQUE INDEX uq_reservation_booking_code(booking_code)');
    $pdo->exec("UPDATE reservations SET booking_code=CONCAT('OLD',id) WHERE booking_code IS NULL");
    $pdo->exec("CREATE TABLE IF NOT EXISTS reservation_day_locks (service_date DATE PRIMARY KEY) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
    $pdo->exec("CREATE TABLE IF NOT EXISTS app_settings (setting_key VARCHAR(64) PRIMARY KEY, setting_value VARCHAR(255) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
    $pdo->exec("INSERT IGNORE INTO app_settings(setting_key,setting_value) VALUES ('booking_open_time','09:00'),('booking_close_time','18:00'),('booking_slot_minutes','60')");
    $pdo->exec("CREATE TABLE IF NOT EXISTS expenses (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, shift_id BIGINT UNSIGNED NULL, expense_date DATETIME NOT NULL, category VARCHAR(60) NOT NULL, description VARCHAR(255) NULL, amount DECIMAL(12,2) NOT NULL, source ENUM('Kas','Non-kas') NOT NULL DEFAULT 'Kas', user_id INT UNSIGNED NOT NULL, created_at DATETIME NOT NULL, INDEX idx_exp_shift(shift_id), INDEX idx_exp_date(expense_date)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
    $pdo->exec("CREATE TABLE IF NOT EXISTS subscriptions (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, start_date DATE NOT NULL, end_date DATE NOT NULL, days INT UNSIGNED NOT NULL, amount DECIMAL(12,2) NOT NULL DEFAULT 0, payment_method VARCHAR(30) NULL, notes VARCHAR(255) NULL, user_id INT UNSIGNED NULL, created_at DATETIME NOT NULL, INDEX idx_sub_end(end_date)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
    $pdo->exec("INSERT INTO subscriptions(start_date,end_date,days,amount,notes,created_at) SELECT CURDATE(),DATE_ADD(CURDATE(),INTERVAL 29 DAY),30,0,'Masa aktif awal (otomatis)',NOW() FROM DUAL WHERE NOT EXISTS(SELECT 1 FROM subscriptions)");
    $productColumns=array_column($pdo->query('SHOW COLUMNS FROM products')->fetchAll(),'Field');
    if(!in_array('cost_price',$productColumns,true))$pdo->exec('ALTER TABLE products ADD COLUMN cost_price DECIMAL(12,2) NOT NULL DEFAULT 0 AFTER unit');
    $pdo->exec("CREATE TABLE IF NOT EXISTS stock_movements (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, product_id INT UNSIGNED NOT NULL, movement_type ENUM('masuk','keluar','penyesuaian') NOT NULL, quantity INT NOT NULL, stock_after INT NOT NULL, unit_cost DECIMAL(12,2) NULL, reference VARCHAR(40) NULL, notes VARCHAR(255) NULL, user_id INT UNSIGNED NOT NULL, created_at DATETIME NOT NULL, INDEX idx_stock_product(product_id,created_at), INDEX idx_stock_date(created_at), FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
    $pdo->exec("INSERT INTO stock_movements(product_id,movement_type,quantity,stock_after,unit_cost,reference,notes,user_id,created_at) SELECT p.id,'masuk',p.stock,p.stock,p.cost_price,'SALDO-AWAL','Saldo sebelum arus stok dicatat',(SELECT MIN(id) FROM users),NOW() FROM products p WHERE p.stock>0 AND (SELECT COUNT(*) FROM users)>0 AND NOT EXISTS(SELECT 1 FROM stock_movements m WHERE m.product_id=p.id)");
    $pdo->exec("CREATE TABLE IF NOT EXISTS shifts (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, status ENUM('buka','tutup') NOT NULL DEFAULT 'buka', opened_by INT UNSIGNED NOT NULL, opened_at DATETIME NOT NULL, opening_cash DECIMAL(12,2) NOT NULL DEFAULT 0, open_notes VARCHAR(255) NULL, closed_by INT UNSIGNED NULL, closed_at DATETIME NULL, cash_sales DECIMAL(12,2) NULL, noncash_sales DECIMAL(12,2) NULL, expected_cash DECIMAL(12,2) NULL, counted_cash DECIMAL(12,2) NULL, difference DECIMAL(12,2) NULL, close_notes VARCHAR(255) NULL, INDEX idx_shift_status(status), FOREIGN KEY(opened_by) REFERENCES users(id) ON DELETE RESTRICT, FOREIGN KEY(closed_by) REFERENCES users(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
    if(!in_array('cash_expenses',array_column($pdo->query('SHOW COLUMNS FROM shifts')->fetchAll(),'Field'),true))$pdo->exec('ALTER TABLE shifts ADD COLUMN cash_expenses DECIMAL(12,2) NULL AFTER noncash_sales');
    $shiftCols=array_column($pdo->query('SHOW COLUMNS FROM shifts')->fetchAll(),'Field');if(!in_array('cash_income',$shiftCols,true))$pdo->exec('ALTER TABLE shifts ADD COLUMN cash_income DECIMAL(12,2) NULL AFTER cash_expenses');
    if(!in_array('kind',array_column($pdo->query('SHOW COLUMNS FROM expenses')->fetchAll(),'Field'),true))$pdo->exec("ALTER TABLE expenses ADD COLUMN kind ENUM('keluar','masuk') NOT NULL DEFAULT 'keluar' AFTER shift_id");
    $visitShiftCols=array_column($pdo->query('SHOW COLUMNS FROM visits')->fetchAll(),'Field');
    if(!in_array('shift_id',$visitShiftCols,true))$pdo->exec('ALTER TABLE visits ADD COLUMN shift_id BIGINT UNSIGNED NULL');
    if(!in_array('therapist_id',$visitShiftCols,true))$pdo->exec('ALTER TABLE visits ADD COLUMN therapist_id INT UNSIGNED NULL');
    if(!in_array('therapist_fee',$visitShiftCols,true))$pdo->exec('ALTER TABLE visits ADD COLUMN therapist_fee DECIMAL(12,2) NULL');
    $visitIndexes=array_column($pdo->query('SHOW INDEX FROM visits')->fetchAll(),'Key_name');
    if(!in_array('idx_visits_shift',$visitIndexes,true))$pdo->exec('ALTER TABLE visits ADD INDEX idx_visits_shift(shift_id)');
}
function availableReservationSlots(PDO $pdo,string $date): array {
    $settings=$pdo->query("SELECT setting_key,setting_value FROM app_settings WHERE setting_key IN ('booking_open_time','booking_close_time','booking_slot_minutes')")->fetchAll(PDO::FETCH_KEY_PAIR);
    $open=preg_match('/^(?:[01][0-9]|2[0-3]):[0-5][0-9]$/',$settings['booking_open_time']??'')?(int)substr($settings['booking_open_time'],0,2)*60+(int)substr($settings['booking_open_time'],3,2):540;
    $close=preg_match('/^(?:[01][0-9]|2[0-3]):[0-5][0-9]$/',$settings['booking_close_time']??'')?(int)substr($settings['booking_close_time'],0,2)*60+(int)substr($settings['booking_close_time'],3,2):1080;
    $duration=(int)($settings['booking_slot_minutes']??60);if(!in_array($duration,[15,30,45,60,90,120],true))$duration=60;
    $dayStart=$date.' 00:00:00';$dayEnd=date('Y-m-d H:i:s',strtotime($date.' +1 day'));$q=$pdo->prepare("SELECT reserved_at FROM reservations WHERE reserved_at>=? AND reserved_at<? AND status<>'Batal'");$q->execute([$dayStart,$dayEnd]);$booked=array_map(fn($r)=>(int)date('G',strtotime($r['reserved_at']))*60+(int)date('i',strtotime($r['reserved_at'])),$q->fetchAll());$now=time();$slots=[];
    for($minute=$open;$minute+$duration<=$close;$minute+=$duration){$startAt=strtotime($date.' '.sprintf('%02d:%02d:00',intdiv($minute,60),$minute%60));if($startAt<=$now)continue;$overlaps=false;foreach($booked as $taken)if($minute<$taken+$duration&&$minute+$duration>$taken){$overlaps=true;break;}if(!$overlaps)$slots[]=sprintf('%02d:%02d',intdiv($minute,60),$minute%60);}
    return $slots;
}
