    $q=$pdo->prepare("SELECT category,COUNT(*) n,SUM(CASE WHEN source='Kas' THEN amount ELSE 0 END) kas,SUM(CASE WHEN source='Kas' THEN 0 ELSE amount END) nonkas,SUM(amount) total FROM expenses WHERE kind='keluar' AND expense_date>=? AND expense_date<? GROUP BY category ORDER BY total DESC");$q->execute([$from,$to]);$expCat=$q->fetchAll();$expTotal=array_sum(array_map(fn($r)=>(float)$r['total'],$expCat));$qi=$pdo->prepare("SELECT COALESCE(SUM(amount),0) FROM expenses WHERE kind='masuk' AND expense_date>=? AND expense_date<?");$qi->execute([$from,$to]);$incTotal=(float)$qi->fetchColumn();$expKas=array_sum(array_map(fn($r)=>(float)$r['kas'],$expCat));$expNon=$expTotal-$expKas;$expRows=array_map(fn($r)=>[e($r['category']),e($r['n']),rupiah($r['kas']),rupiah($r['nonkas']),'<strong>'.rupiah($r['total']).'</strong>'],$expCat);if($expRows)$expRows[]=['<strong>Total</strong>',e(array_sum(array_map(fn($r)=>(int)$r['n'],$expCat))),'<strong>'.rupiah($expKas).'</strong>','<strong>'.rupiah($expNon).'</strong>','<strong>'.rupiah($expTotal).'</strong>'];
