    const catalog=document.getElementById("catalog-select"),cartLines=document.getElementById("cart-lines"),cartTotal=document.getElementById("cart-total"),submitCheckout=document.getElementById("checkout-submit"),cart=new Map(),spvPin=document.getElementById("spv-pin"),spvReason=document.getElementById("spv-reason"),cartSummary=[];let memberRate=false,spvOpen=false;
