    function drawCart(){refreshCatalog();cartLines.replaceChildren();cartSummary.length=0;let total=0,adjusted=false;for(const [key,item] of cart){const price=item.kind==="product"?item.price:(memberRate?item.member:item.normal),line=document.createElement("div");line.className="cart-line";const name=document.createElement("strong");name.textContent=item.label;const priceText=document.createElement("span");priceText.textContent=currency(price);const qty=document.createElement("input");qty.type="number";qty.min="1";qty.max=item.stock||999;qty.value=item.qty;qty.setAttribute("aria-label","Jumlah "+item.label);qty.addEventListener("change",()=>{item.qty=Math.max(1,Math.min(Number(qty.max),Number(qty.value)||1));drawCart()});const remove=document.createElement("button");remove.type="button";remove.className="smallbtn danger";remove.textContent="Hapus";remove.addEventListener("click",()=>{cart.delete(key);drawCart()});const hidden=document.createElement("input");hidden.type="hidden";hidden.name="cart["+item.kind+"]["+item.id+"]";hidden.value=item.qty;line.append(name,priceText,qty,remove,hidden);if(item.kind==="treatment"){const isT=item.ttype==="transport",wrap=document.createElement("label"),cap=document.createElement("span"),pick=document.createElement("select");wrap.className="cart-therapist";cap.textContent=isT?"Kendaraan":"Terapis";pick.name="therapist["+item.id+"]";pick.required=!isT;pick.setAttribute("aria-label",(isT?"Kendaraan untuk ":"Terapis untuk ")+item.label);pick.append(new Option(isT?"Motor toko / bukan pegawai":"Pilih terapis",""));for(const th of therapists)pick.add(new Option(isT?"Motor "+th.name+" (ongkir jadi pendapatan)":th.name,th.id));pick.value=item.therapist||(isT?"":lastTherapist)||"";item.therapist=pick.value;pick.addEventListener("change",()=>{item.therapist=pick.value;if(!isT)lastTherapist=pick.value});wrap.append(cap,pick);line.append(wrap)}const po=spvOpen?item.po:undefined,unit=(po!==undefined&&po!==""&&!isNaN(Number(po)))?Number(po):pri