        return [e(date('d/m/Y H:i',strtotime($r['dt']))),'<span class="status '.e($badge[$r['jenis']]??'').'">'.e($r['jenis']).'</span>','<strong>'.e($r['kategori']).'</strong>'.($r['ket']!==''?'<small class="muted" style="display:block">'.e($r['ket']).'</small>':''),e($src).($kas?'':' <small class="muted">(bukan kas)</small>'),(float)$r['masuk']>0?'<span class="amt-in">+'.rupiah($r['masuk']).'</span>':'',(float)$r['keluar']>0?'<span class="amt-out">−'.rupiah($r['keluar']).'</span>':'',e($r['petugas']??'-'),$act];},$L['rows']);
